#!/usr/bin/env node
/**
 * Supr UI — push the generated Variables REST payload into a Figma file.
 *
 *   FIGMA_TOKEN=... FIGMA_FILE_KEY=... node figma-plugin/scripts/apply-rest.mjs
 *
 * Reads figma-plugin/variables-rest.json (generated by sync-tokens.mjs) and
 * POSTs it to POST /v1/files/:file_key/variables. Requires a Figma personal
 * access token with the file_variables:write scope and edit access to the
 * file. Figma gates this endpoint to full members of Enterprise orgs — a
 * 403 with "Limited by Figma plan" means the file's org is not Enterprise;
 * use the plugin path instead (it works on any plan).
 *
 * The payload is CREATE-only and one atomic request: on a file that already
 * has these variables it will fail with duplicate-name errors. For a
 * re-sync, delete the six collections in Figma first, or use the plugin,
 * which updates in place. Untested here (no Figma access in this sandbox).
 */
import { readFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const PLUGIN_DIR = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

const token = process.env.FIGMA_TOKEN;
const fileKey = process.env.FIGMA_FILE_KEY;
if (!token) {
  console.error('Missing FIGMA_TOKEN (Figma personal access token, file_variables:write scope).');
  process.exit(2);
}
if (!fileKey) {
  console.error('Missing FIGMA_FILE_KEY (the file key from the Figma file URL).');
  process.exit(2);
}

const payload = await readFile(path.join(PLUGIN_DIR, 'variables-rest.json'), 'utf8');

const response = await fetch(`https://api.figma.com/v1/files/${encodeURIComponent(fileKey)}/variables`, {
  method: 'POST',
  headers: { 'X-Figma-Token': token, 'Content-Type': 'application/json' },
  body: payload,
});

const body = await response.json().catch(() => null);
if (!response.ok) {
  console.error(`Figma rejected the request (${response.status}): ${JSON.stringify(body)}`);
  if (response.status === 403) {
    console.error('Hint: the Variables REST API is Enterprise-only. Use the Figma plugin instead — see figma-plugin/README.md.');
  }
  process.exit(1);
}

console.log('Variables applied.');
console.log('tempIdToRealId mapping:', JSON.stringify(body?.meta?.tempIdToRealId ?? {}, null, 2));
